import {escape,SERVICES,money,time,MIN_DATE,MAX_DATE,firstOpenDate,SAMPLE_BUSY,quote,slots,savePlan} from "./assets/engine.js";
const $=id=>document.getElementById(id),icon=name=>`<svg aria-hidden="true"><use href="./assets/icons.svg#${name}"></use></svg>`;let plans=[],offerUsed=false,draft=null,baseline="",step=1,confirmAction=null,detailId=null,toastTimer;
const snapshot=()=>JSON.stringify([draft.ids,draft.date,draft.start,draft.offer]),dateText=date=>new Intl.DateTimeFormat("en-PH",{weekday:"short",day:"numeric",month:"long",year:"numeric",timeZone:"UTC"}).format(new Date(date+"T12:00:00Z"));
const pricing=()=>draft.editId?plans.find(p=>p.id===draft.editId)?.quote:quote(draft.ids,draft.offer,offerUsed);
function toast(text){$("toast").textContent=text;$("toast").hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$("toast").hidden=true,4200);}
function confirm(title,description,label,action){$("confirm-title").textContent=title;$("confirm-description").textContent=description;$("confirm-action").textContent=label;confirmAction=action;$("confirm-dialog").showModal();}
$("confirm-action").addEventListener("click",()=>{const action=confirmAction;confirmAction=null;$("confirm-dialog").close();action?.();});
function renderServices(category=""){$("service-grid").innerHTML=SERVICES.filter(s=>!category||s.category===category).map(s=>`<article class="service-card" data-service="${s.id}"><button data-details="${s.id}" aria-label="Read about ${escape(s.name)}"><img src="./assets/${s.image}" alt="Original care-concept illustration for ${escape(s.name)}" loading="lazy"></button><span class="eyebrow">${s.eyebrow}</span><h3>${escape(s.name)}</h3><p>${s.duration} minutes · ${s.category}</p><div class="card-foot"><span>${s.price?money(s.price):"Sample complimentary"}</span><button class="text-link" data-book="${s.id}">Preview visit ${icon("arrow")}</button></div></article>`).join("");}
function openDetail(id){const s=SERVICES.find(s=>s.id===id);if(!s)return;detailId=id;$("service-title").textContent=s.name;$("detail-eyebrow").textContent=s.eyebrow;$("detail-description").textContent=s.description;$("detail-art").src="./assets/"+s.image;$("detail-art").alt="Original illustration for "+s.name;$("detail-meta").innerHTML=`<span>${s.duration} minutes · ${escape(s.category)}</span><span>${s.price?money(s.price):"Sample complimentary"}</span>`;$("service-dialog").showModal();}
function openBooking(id="",offer=false,editId=null){
  const existing=editId?plans.find(p=>p.id===editId&&p.status==="planned"):null;if(editId&&!existing)return;
  draft={id:existing?.id||"demo-"+crypto.randomUUID().slice(0,8),editId,ids:existing?existing.quote.services.map(s=>s.id):id?[id]:[],date:existing?.date||firstOpenDate(),start:existing?.start??null,offer:offer&&!offerUsed,saved:false};baseline=snapshot();step=existing?2:1;$("booking-title").textContent=existing?"A different little moment.":"Make a little room.";renderBooking();$("booking-dialog").showModal();
}
function closeBooking(){if(!draft||draft.saved||snapshot()===baseline){$("booking-dialog").close();return;}confirm("Leave this little plan?","The unsaved choices will be discarded. Your saved local plans stay as they are.","Discard this draft",()=>$("booking-dialog").close());}
function summary(q){return `<div class="price-summary"><div><span>Sample care total</span><span>${money(q.subtotal)}</span></div><div><span>${q.duration} minutes · one sample chair</span><span></span></div>${q.discount?`<div><span>WELCOME10 · sample discount</span><span>−${money(q.discount)}</span></div>`:""}<div><strong>Illustrative total</strong><strong>${money(q.total)}</strong></div></div>`;}
function renderBooking(){
  document.querySelectorAll("#step-indicator span").forEach((el,index)=>{el.classList.toggle("active",index+1===step);if(index+1===step)el.setAttribute("aria-current","step");else el.removeAttribute("aria-current");});
  if(step===1){$("booking-body").innerHTML=`<div class="care-choices">${SERVICES.map(s=>`<label class="care-choice"><input type="checkbox" name="care" value="${s.id}"${draft.ids.includes(s.id)?" checked":""}><span><strong>${escape(s.name)}</strong><small>${s.duration} min · ${s.category}</small></span><b>${s.price?money(s.price):"PHP 0"}</b></label>`).join("")}</div><p class="unit-note">Choose one to three options. These are sample menu entries, not medical recommendations.</p><label class="offer-check"><input id="offer-code" type="checkbox"${draft.offer?" checked":""}${offerUsed?" disabled":""}><span>Apply WELCOME10 · 10% sample discount<small>${offerUsed?"Already used in this page session.":"One paid sample plan per page session. No real promotion."}</small></span></label><div id="price-container"></div><p class="planner-error" id="planner-error" role="alert"></p><div class="dialog-actions"><button class="secondary" id="draft-close">Close preview</button><button class="primary" id="continue"${draft.ids.length?"":" disabled"}>Choose a moment ${icon("right")}</button></div>`;updateQuote();return;}
  if(step===2){const q=pricing();$("booking-body").innerHTML=`<p class="review-care">${q.services.map(s=>escape(s.name)).join(" + ")}</p><p class="unit-note">${q.duration} minutes · illustrative total ${money(q.total)}${draft.editId?" · Original quote is preserved.":""}</p><label class="date-label">Your sample date<input id="visit-date" type="date" min="${MIN_DATE}" max="${MAX_DATE}" value="${draft.date}"></label><div class="slot-heading"><strong>Choose your quiet moment</strong><span>LOCAL CALENDAR DATES · 24-HOUR TIMES</span></div><div class="slots" id="slots"></div><p class="sample-rules">Sample hours Mon–Sat 09:00–12:00 / 13:00–17:00. One chair; lunch and overlapping plans are excluded. Example occupied block: ${dateText(SAMPLE_BUSY.date)}, 10:00–11:00. Tomorrow through 30 days ahead.</p>${summary(q)}<p class="planner-error" id="planner-error" role="alert"></p><div class="dialog-actions"><button class="secondary" id="${draft.editId?"draft-close":"back"}">${draft.editId?"Keep original plan":"Back to care"}</button><button class="primary" id="save-plan"${draft.start===null?" disabled":""}>${draft.editId?"Save new sample time":"Save demo plan"} ${icon("check")}</button></div>`;renderSlots();return;}
  const plan=plans.find(p=>p.id===draft.id);$("booking-body").innerHTML=`<div class="receipt"><span class="receipt-icon">${icon("check")}</span><span class="eyebrow">SAVED IN THIS BROWSER TAB ONLY</span><h3>A little pause, planned.</h3><p>${plan.quote.services.map(s=>escape(s.name)).join(" + ")}</p><p>${dateText(plan.date)} · ${time(plan.start)}–${time(plan.start+plan.quote.duration)}</p><p>${money(plan.quote.total)} · illustrative, unpaid</p><p class="receipt-notice">This is not a confirmed appointment. No clinic was contacted, no reservation was held, and no payment or email was sent. Refreshing clears the plan.</p></div><div class="dialog-actions"><button class="secondary" id="draft-close">Back to the page</button><button class="primary" id="view-plans">View demo plans ${icon("arrow")}</button></div>`;
}
function updateQuote(){if(!draft.ids.length){$("price-container").innerHTML="";$("continue").disabled=true;return;}try{$("price-container").innerHTML=summary(quote(draft.ids,draft.offer,offerUsed));$("continue").disabled=false;}catch(e){$("planner-error").textContent=e.message;$("continue").disabled=true;}}
function renderSlots(){const values=slots(draft.date,pricing().duration,plans,draft.editId);if(!values.includes(draft.start))draft.start=null;$("slots").innerHTML=values.length?values.map(value=>`<button class="slot${draft.start===value?" active":""}" data-slot="${value}" aria-pressed="${draft.start===value}">${time(value)}</button>`).join(""):`<p class="no-slots">No sample times on this date. Choose an open Monday–Saturday within the next 30 days.</p>`;$("save-plan").disabled=draft.start===null;}
function renderPlans(){$("plan-count").textContent=plans.filter(p=>p.status==="planned").length;$("plans-list").innerHTML=plans.length?[...plans].sort((a,b)=>a.date.localeCompare(b.date)||a.start-b.start).map(p=>`<article class="local-plan ${p.status}" data-plan="${p.id}"><div><h3>${p.quote.services.map(s=>escape(s.name)).join(" + ")}</h3><span class="status">${p.status==="planned"?"Planned locally":"Cancelled locally"}</span></div><p>${dateText(p.date)} · ${time(p.start)}–${time(p.start+p.quote.duration)}</p><p>${money(p.quote.total)} · illustrative, unpaid${p.quote.discount?" · WELCOME10 included":""}</p>${p.status==="planned"?`<div class="plan-buttons"><button class="text-button" data-reschedule="${p.id}">Try another time</button><button class="text-button" data-cancel="${p.id}">Cancel local plan</button></div>`:""}</article>`).join(""):`<p class="empty-plans">Nothing planned yet. Take your time exploring the sample menu.</p>`;$("plans-new").disabled=plans.length>=8;}
function showPlans(){renderPlans();$("plans-dialog").showModal();}
function save(){
  if(draft.saved)return;try{const result=savePlan(plans,draft,offerUsed);plans=result.plans;offerUsed=result.offerUsed;draft.saved=true;step=3;renderPlans();renderBooking();}catch(e){$("planner-error").textContent=e.message;}
}
document.addEventListener("click",event=>{
  const button=event.target.closest("button");if(!button)return;
  if(button.hasAttribute("data-book"))openBooking(button.dataset.book);
  if(button.dataset.close)$(button.dataset.close).close();
  if(button.hasAttribute("data-details"))openDetail(button.dataset.details);
  if(button.hasAttribute("data-filter")){document.querySelectorAll("[data-filter]").forEach(b=>{b.classList.toggle("active",b===button);b.setAttribute("aria-pressed",b===button);});renderServices(button.dataset.filter);}
  if(button.hasAttribute("data-slot")){draft.start=Number(button.dataset.slot);renderSlots();}
  if(button.hasAttribute("data-reschedule")){$("plans-dialog").close();openBooking("",false,button.dataset.reschedule);}
  if(button.hasAttribute("data-cancel")){const id=button.dataset.cancel;confirm("Release this little pause?","This cancels only the local sample plan and releases its sample time. A used welcome offer stays used.","Cancel local plan",()=>{plans=plans.map(p=>p.id===id?{...p,status:"cancelled"}:p);renderPlans();const row=document.querySelector(`[data-plan="${id}"]`);row.tabIndex=-1;row.focus();});}
});
$("booking-body").addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;if(b.id==="continue"){if(!draft.ids.length||draft.ids.length>3)return;step=2;renderBooking();$("booking-dialog").scrollTop=0;}if(b.id==="back"){step=1;renderBooking();$("booking-dialog").scrollTop=0;}if(b.id==="save-plan")save();if(b.id==="draft-close")closeBooking();if(b.id==="view-plans"){$("booking-dialog").close();showPlans();}});
$("booking-body").addEventListener("change",e=>{if(e.target.name==="care"){const ids=[...document.querySelectorAll("input[name=care]:checked")].map(el=>el.value);if(ids.length>3){e.target.checked=false;$("planner-error").textContent="Choose up to three options for one sample visit.";return;}draft.ids=ids;draft.start=null;$("planner-error").textContent="";updateQuote();}if(e.target.id==="offer-code"){draft.offer=e.target.checked;updateQuote();}if(e.target.id==="visit-date"){draft.date=e.target.value;draft.start=null;$("planner-error").textContent="";renderSlots();}});
$("booking-close").addEventListener("click",closeBooking);$("booking-dialog").addEventListener("cancel",e=>{e.preventDefault();closeBooking();});$("plans").addEventListener("click",showPlans);$("plans-new").addEventListener("click",()=>{$("plans-dialog").close();openBooking();});$("welcome").addEventListener("click",()=>{if(offerUsed)toast("The sample welcome offer was already used. You can still preview a regular plan.");openBooking("",true);});$("about").addEventListener("click",()=>$("about-dialog").showModal());$("detail-book").addEventListener("click",()=>{$("service-dialog").close();openBooking(detailId);});
renderServices();renderPlans();
